create table if not exists public.kiru_flashcard_sets (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, created_by uuid not null references public.profiles(id) on delete restrict, title text not null check (length(trim(title)) between 1 and 180), subject text not null default 'General', source_file_name text, source_storage_path text, source_mime_type text, source_size_bytes bigint check (source_size_bytes is null or source_size_bytes between 0 and 20971520), generation_method text not null default 'manual' check (generation_method in ('manual','document_rules','ai')), status text not null default 'draft' check (status in ('draft','published','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists kiru_flashcard_sets_student_updated_idx on public.kiru_flashcard_sets(student_id, updated_at desc); create table if not exists public.kiru_flashcards (id uuid primary key default gen_random_uuid(), set_id uuid not null references public.kiru_flashcard_sets(id) on delete cascade, term text not null check (length(trim(term)) between 1 and 1000), definition text not null check (length(trim(definition)) between 1 and 5000), position integer not null default 0 check (position >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(set_id, position)); create index if not exists kiru_flashcards_set_position_idx on public.kiru_flashcards(set_id, position); alter table public.kiru_flashcard_sets enable row level security; alter table public.kiru_flashcards enable row level security; create policy kiru_flashcard_sets_read_related on public.kiru_flashcard_sets for select to authenticated using (student_id = (select auth.uid()) or ((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') or exists(select 1 from public.student_mentors sm where sm.student_id = kiru_flashcard_sets.student_id and sm.mentor_id = (select auth.uid())) or exists(select 1 from public.student_guardians sg where sg.student_id = kiru_flashcard_sets.student_id and sg.guardian_id = (select auth.uid()))); create policy kiru_flashcard_sets_insert_mentor_admin on public.kiru_flashcard_sets for insert to authenticated with check (created_by = (select auth.uid()) and (((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') or exists(select 1 from public.student_mentors sm where sm.student_id = kiru_flashcard_sets.student_id and sm.mentor_id = (select auth.uid())))); create policy kiru_flashcard_sets_update_mentor_admin on public.kiru_flashcard_sets for update to authenticated using (((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') or (created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = kiru_flashcard_sets.student_id and sm.mentor_id = (select auth.uid())))) with check (((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') or (created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = kiru_flashcard_sets.student_id and sm.mentor_id = (select auth.uid())))); create policy kiru_flashcard_sets_delete_mentor_admin on public.kiru_flashcard_sets for delete to authenticated using (((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') or (created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = kiru_flashcard_sets.student_id and sm.mentor_id = (select auth.uid())))); create policy kiru_flashcards_read_related on public.kiru_flashcards for select to authenticated using (exists(select 1 from public.kiru_flashcard_sets s where s.id = kiru_flashcards.set_id)); create policy kiru_flashcards_insert_mentor_admin on public.kiru_flashcards for insert to authenticated with check (exists(select 1 from public.kiru_flashcard_sets s where s.id = kiru_flashcards.set_id and (s.created_by = (select auth.uid()) or (select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin') and ((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin' or exists(select 1 from public.student_mentors sm where sm.student_id = s.student_id and sm.mentor_id = (select auth.uid()))))); create policy kiru_flashcards_update_mentor_admin on public.kiru_flashcards for update to authenticated using (exists(select 1 from public.kiru_flashcard_sets s where s.id = kiru_flashcards.set_id and ((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin' or (s.created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = s.student_id and sm.mentor_id = (select auth.uid())))))) with check (exists(select 1 from public.kiru_flashcard_sets s where s.id = kiru_flashcards.set_id and ((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin' or (s.created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = s.student_id and sm.mentor_id = (select auth.uid())))))); create policy kiru_flashcards_delete_mentor_admin on public.kiru_flashcards for delete to authenticated using (exists(select 1 from public.kiru_flashcard_sets s where s.id = kiru_flashcards.set_id and ((select auth.jwt() -> 'app_metadata' ->> 'kiru_role') = 'admin' or (s.created_by = (select auth.uid()) and exists(select 1 from public.student_mentors sm where sm.student_id = s.student_id and sm.mentor_id = (select auth.uid()))))));
